      "arFull": "لَاُعَذِّبَنَّهٗ عَذَابًا شَدِیْدًا اَوْ لَاَاَذْبَحَنَّهٗۤ اَوْ لَیَاْتِیَنِّیْ بِسُلْطٰنٍ مُّبِیْنٍ ۟",
