      "arFull": "فَانْظُرْ كَیْفَ كَانَ عَاقِبَةُ مَكْرِهِمْ ۙ اَنَّا دَمَّرْنٰهُمْ وَقَوْمَهُمْ اَجْمَعِیْنَ ۟",
