      "number": 79,
      "arFull": "فَتَوَكَّلْ عَلَی اللّٰهِ ؕ اِنَّكَ عَلَی الْحَقِّ الْمُبِیْنِ ۟",
      "ur": "پس آپ یقیناً اللہ ہی پر بھروسہ رکھیے، یقیناً آپ سچے اور کھلے دین پر ہیں.[1]",
